head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.chrgTpCdArr = [];

///////// 2. 초기화 영역 /////////
scwin.onpageload = async function() {
	try {

	    const sbmOptions = {
	        id : "sbm_SelectChrgLiqu",
	        action : "/api/discls/info/chrg/liqu/select-list",
	        method : "get",
	        target : "dma_DiscRes=body",
	        isProcessMsg : false
	    };

	    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
	    scwin.sbm_SelectChrgLiqu_submitdone(sbmRtn);

	    // 로그인한 법인의 담당자구분코드 정보 조회
	    const sbmOptions2 = {
	        id : "sbm_SelectChrgTpCd",
	        action : "/api/discls/info/chrg/tp-cd/select-list?lpYn=Y",
	        method : "get",
	        isProcessMsg : false
	    };

	    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
	    scwin.sbm_SelectChrgTpCd_submitdone(sbmRtn2);
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "JLDFIL25111.onpageload" });
	}
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/// EVENT ///

/**
 * 이메일 도메인 선택
 */
scwin.sel_email_onviewchange = function (info) {
	try {
		const domain = info.newValue;
	    const idx = this.getUserData("userData1");
	    const iptObj = $p.getComponentById("ipt_email2_"+idx);
	    if(iptObj) {
	        iptObj.setValue(domain);
	    }
	} catch (ex) {
		$c.exception.handleError(ex, { context : "JLDFIL25111.sel_email_onviewchange" });
	}
};

/**
 * 우편번호 버튼 클릭
 */
scwin.btn_popZipCode_onclick = function (e) {
    try {
        let idx = this.getUserData("userData1");
    	scwin.popZipCode(idx);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "JLDFIL25111.btn_popZipCode_onclick" });
    }
};

/**
 * 재등록 버튼 클릭
 */
scwin.btn_insert_onclick = function (e) {
    try {
        const idx = this.getUserData("userData1");
        scwin.modify("insert", idx);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "JLDFIL25111.btn_insert_onclick" });
    }
};

/**
 * 수정 버튼 클릭
 */
scwin.btn_update_onclick = function (e) {
    try {
        const idx = this.getUserData("userData1");
        scwin.modify("update", idx);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "JLDFIL25111.btn_update_onclick" });
    }
};

/**
 * 삭제 버튼 클릭
 */
scwin.btn_delete_onclick = function (e) {
    try {
        const idx = this.getUserData("userData1");
        scwin.delete(idx);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "JLDFIL25111.btn_delete_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/// SUBMISSION ///
scwin.sbm_SelectChrgLiqu_submitdone = function (e) {
	const res = e.responseJSON;
    const body = res.body;

    // 1.업무책임자
    if(body.corpDisclsChrg1) {
        dma_CorpDisclsChrg1.setJSON(body.corpDisclsChrg1);
        scwin.initEditView(1);
    } else {
        // 지정일(수정X, 재등록 시에만 활성화)
        grp_view_chrgDesignDd_1.hide();
        grp_edit_chrgDesignDd_1.show("");
    }

    // 2.업무담당자(정)
    if(body.corpDisclsChrg2) {
        dma_CorpDisclsChrg2.setJSON(body.corpDisclsChrg2);
        scwin.initEditView(2);
    } else {
        // 지정일(수정X, 재등록 시에만 활성화)
        grp_view_chrgDesignDd_2.hide();
        grp_edit_chrgDesignDd_2.show("");
    }

    // 3.업무담당자(부)
    if(body.corpDisclsChrg3) {
        dma_CorpDisclsChrg3.setJSON(body.corpDisclsChrg3);
        scwin.initEditView(3);
    } else {
        // 지정일(수정X, 재등록 시에만 활성화)
        grp_view_chrgDesignDd_3.hide();
        grp_edit_chrgDesignDd_3.show("");
    }
};

scwin.sbm_UpsertDisclsInfoLiqu_submitdone = function (e) {
	const res = e.responseJSON;
    if(dma_CorpDisclsChrgReq.get("chrgNm") === res.body) {
	    alert('요청하신 작업을 완료하였습니다.');
    }
    $p.reinitialize();
};

scwin.sbm_DeleteDisclsInfoLiqu_submitdone = function (e) {
    const res = e.responseJSON;
    if(dma_CorpDisclsChrgReq.get("chrgTpCd") === res.body) {
	    alert('요청하신 작업을 완료하였습니다.');
    }
    $p.reinitialize();
};

scwin.sbm_SelectChrgTpCd_submitdone = function (e) {
    const res = e.responseJSON;
    scwin.chrgTpCdArr = res.body;
};

/**
 * 우편번호 검색 콜백함수
 */
scwin.popZipCodeCallback = function (result) {
    const idx = result.req.idx;
    const zipcdObj = $p.getComponentById("ipt_locZipcd_"+idx);
    const addrObj = $p.getComponentById("ipt_locAddr_"+idx);
    const dtlAddrObj = $p.getComponentById("ipt_locDtlAddr_"+idx);

    zipcdObj.setValue(result.zipNo);
    addrObj.setValue(result.addr);
    dtlAddrObj.setValue("");
};

/**
 * 재등록 및 수정
 */
scwin.modify = async function (type, idx) {
    // const grpObj = $p.getComponentById("grp_corpDisclsChrg_"+idx);

    const obj_chrgNm = $p.getComponentById("ipt_chrgNm_"+idx);
    const obj_jobtitlNm = $p.getComponentById("ipt_jobtitlNm_"+idx);
    const obj_depNm = $p.getComponentById("ipt_depNm_"+idx);
    const obj_telNo = $p.getComponentById("ipt_telNo_"+idx);
    const obj_chrgInnrNo = $p.getComponentById("ipt_chrgInnrNo_"+idx);
    const obj_cellphoneNo = $p.getComponentById("ipt_cellphoneNo_"+idx);
    const obj_faxNo = $p.getComponentById("ipt_faxNo_"+idx);
    const obj_email = $p.getComponentById("ipt_email_"+idx);
    const obj_email1 = $p.getComponentById("ipt_email1_"+idx);
    const obj_email2 = $p.getComponentById("ipt_email2_"+idx);
    const obj_locZipcd = $p.getComponentById("ipt_locZipcd_"+idx);
    const obj_locAddr = $p.getComponentById("ipt_locAddr_"+idx);
    const obj_locDtlAddr = $p.getComponentById("ipt_locDtlAddr_"+idx);
    const obj_chrgDesignDd = $p.getComponentById("ipt_chrgDesignDd_"+idx); // 지정일
    const obj_yyyy = $p.getComponentById("ipt_yyyy_"+idx);
    const obj_mm = $p.getComponentById("ipt_mm_"+idx);
    const obj_dd = $p.getComponentById("ipt_dd_"+idx);

    // TODO : 공통 적용 예정
    /*
    if(type == "insert") {
        // 성명 체크
        if($c.cm.fn_NullChk(obj_chrgNm)){
            return;
        }
        if($c.cm.fn_IsExceedMaxLen(obj_chrgNm)){
            return;
        }
    }

    // 직위 체크
    if($c.cm.fn_NullChk(obj_jobtitlNm)){
        return;
    }
    if($c.cm.fn_IsExceedMaxLen(obj_jobtitlNm)){
        return;
    }		

    // 부서 체크
    if($c.cm.fn_NullChk(obj_depNm)){
        return;
    }				
    if($c.cm.fn_IsExceedMaxLen(obj_depNm)){
        return;
    }	

    // 유선전화번호 NULL 체크
    if($c.cm.fn_NullChk(obj_telNo)){
        return;
    }
    if($c.cm.fn_IsExceedMaxLen(obj_telNo)){
        return;
    }

    // 휴대전화번호 NULL 체크
    if($c.cm.fn_NullChk(obj_cellphoneNo)){
        return;
    }				
    if($c.cm.fn_IsExceedMaxLen(obj_cellphoneNo)){
        return;
    }

    // FAX NULL 체크
    if($c.cm.fn_NullChk(obj_faxNo)){
        return;
    }		
    if($c.cm.fn_IsExceedMaxLen(obj_faxNo)){
        return;
    }

    // E-Mail NULL 체크
    if($c.cm.fn_NullChk(obj_email1) || $c.cm.fn_NullChk(obj_email2)){
        return;
    }

    // 주소 체크
    if($c.cm.fn_NullChk(obj_locAddr)){
        return;
    }				
    if($c.cm.fn_IsExceedMaxLen(obj_locAddr)){
        return;
    }		

    // email 체크
    if(!$c.cm.fn_CheckEmail(obj_email.getValue())){
        return;
    }	

    // 지정일 체크
    if($c.cm.fn_NullChk(obj_yyyy) || $c.cm.fn_NullChk(obj_mm) || $c.cm.fn_NullChk(obj_dd)){
        return;
    }	
    */	

    // 지정일 형식 맞추기
    let chrgDesignDd = obj_yyyy.getValue() + obj_mm.getValue() + obj_dd.getValue();
    obj_chrgDesignDd.setValue(chrgDesignDd);

    // 이메일 형식 맞추기
    let email = obj_email1.getValue() + '@' + obj_email2.getValue();
    obj_email.setValue(email);

    if(idx === 1) {
        dma_CorpDisclsChrgReq.setJSON(dma_CorpDisclsChrg1.getJSON());
    }else if(idx === 2) {
        dma_CorpDisclsChrgReq.setJSON(dma_CorpDisclsChrg2.getJSON());
    }else if(idx === 3) {
        dma_CorpDisclsChrgReq.setJSON(dma_CorpDisclsChrg3.getJSON());
    }

    if(type === "insert") {
        scwin.setChrgTp(idx);
        // $c.sbm.execute(sbm_InsertDisclsInfoLiqu);
    } else if(type === "update") {
