            id : "sbm_UpdateDisclsInfoLiqu",
            action : "/api/discls/info/chrg/liqu/update",
            ref : "dma_CorpDisclsChrgReq",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        scwin.sbm_UpsertDisclsInfoLiqu_submitdone(sbmRtn);
    }

};

/**
 * 삭제
 */
scwin.delete = async function (idx) {
    if(confirm('정말 삭제하시겠습니까?')) {        
        if(idx === 1) {
            dma_CorpDisclsChrgReq.setJSON(dma_CorpDisclsChrg1.getJSON());
        }else if(idx === 2) {
            dma_CorpDisclsChrgReq.setJSON(dma_CorpDisclsChrg2.getJSON());
        }else if(idx === 3) {
            dma_CorpDisclsChrgReq.setJSON(dma_CorpDisclsChrg3.getJSON());
        }

        const sbmOptions = {
            id : "sbm_DeleteDisclsInfoLiqu",
            action : "/api/discls/info/chrg/liqu/delete",
            ref : "dma_CorpDisclsChrgReq",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        scwin.sbm_DeleteDisclsInfoLiqu_submitdone(sbmRtn);
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/// FUNCTION ///

/**
 * 수정화면 초기값 세팅
 */
scwin.initEditView = function (idx) {
    // 이메일
    let emailObj = $p.getComponentById("ipt_email_"+idx);
    let email = emailObj.getValue();

    let email_1_Obj = $p.getComponentById("ipt_email1_"+idx);
    let email_2_Obj = $p.getComponentById("ipt_email2_"+idx);
    email_1_Obj.setValue(scwin.emailFormat(email));
    email_2_Obj.setValue(scwin.emailFormatDomain(email));

    // 지정일
    let chrgDesignDdObj = $p.getComponentById("ipt_chrgDesignDd_"+idx);
    let dateArr = scwin.getDateSplit(chrgDesignDdObj.getValue());
    if(dateArr && dateArr.yyyy && dateArr.mm && dateArr.dd) {
        $p.getComponentById("ipt_yyyy_"+idx).setValue(dateArr.yyyy);
        $p.getComponentById("ipt_mm_"+idx).setValue(dateArr.mm);
        $p.getComponentById("ipt_dd_"+idx).setValue(dateArr.dd);
    }

    // 수정 폼 표시
    $p.getComponentById("grp_i_chrgNm_"+idx).hide();
    $p.getComponentById("grp_i_trigger_"+idx).hide();
    $p.getComponentById("grp_u_chrgNm_"+idx).show("");
    $p.getComponentById("grp_u_trigger_"+idx).show("");

};

/**
 * 우편번호 검색
 */
scwin.popZipCode = function (idx) {
    const options = {
        id: "ZipWinPop",
        type: "browserPopup",
        width: "650px",        
        height: "720px",
        resizable: true
    };
    const param = {
        "data": {"idx": idx},
        "callbackFn": "scwin.fn_popZipCodeCallback"
    };
    $c.win.openPopup("/ui/dis/common/popup_roadZipcode.xml", options, param);

};

/**
 * 날짜포맷
 * @DESC : yyyyMMdd -> yyyy년 MM월 dd일
 */
scwin.dateFormat = function (str) {
    if(str && str.length === 8) {
        let yyyy = str.substring(0, 4);
        let mm = str.substring(4, 6);
        let dd = str.substring(6, 8);
        return yyyy + "년 " + mm + "월 " + dd + "일";
    } else {
        return str;
    }
};

/**
 * 날짜 분리하여 리턴
 * @DESC : 20260610 -> {yyyy: "2026", mm: "06", dd:"10"}
 */
scwin.getDateSplit = function (str) {
    let result = {
        yyyy: "",
        mm: "",
        dd: ""
    };

    if(str && str.length === 8) {
        let yyyy = str.substring(0, 4);
        let mm = str.substring(4, 6);
        let dd = str.substring(6, 8);
        result["yyyy"] = yyyy;
        result["mm"] = mm;
        result["dd"] = dd;
    }

    return result;
};

/**
 * 이메일포맷
 * @DESC : eds@krx.co.kr -> eds
 */
scwin.emailFormat = function (str) {
    if(str) {
        let endIdx = str.indexOf('@');
        if(endIdx > -1) {
            str = str.substring(0, endIdx);
        }
    }
    return str;
};

/**
 * 이메일포맷 도메인
 * @DESC : eds@krx.co.kr -> @krx.co.kr
 */
scwin.emailFormatDomain = function (str) {
    if(str) {
        let startIdx = str.indexOf('@')+1;
        str = str.substring(startIdx);
    }
    return str;
};

/**
 * 담당자 구분코드 세팅
 * @DESC : 재등록 가능한 경우만 필요
 */
scwin.setChrgTp = function (idx) {
    let i = Number(idx) - 1;

    if(scwin.chrgTpCdArr[i]) {
        const chrgTpCd = scwin.chrgTpCdArr[i];
        dma_CorpDisclsChrgReq.set("chrgTpCd", chrgTpCd);
    }
};
